public void processFile(String path) {
    try {
        // Checked exception: Caller must handle or rethrow
        Files.readAllLines(Paths.get(path));
    } catch (IOException e) {
        // Wrap in unchecked exception to maintain clean API boundaries
        throw new DataProcessingException("Failed to load config: " + path, e);
    }
}

public void validateInput(String data) {
    // Unchecked exception: Logic error, no need to force caller to catch
    if (data == null) {
        throw new IllegalArgumentException("Data cannot be null");
    }
}
